-- Seed de DEMONSTRAÇÃO: cotações oficiais USD/VES do BCV, 01/01/2026 a 09/10/2026.
-- Independente dos outros seeds, mas precisa rodar ANTES de 05 (pagamentos em VES apontam pra
-- cotação do dia por FK, e as telas usam o histórico pra mostrar o Bs. de pagamentos em USD).
--
-- Fonte: série histórica real USD/VES (coluna "Último"), só dias úteis. Fim de semana e feriado
-- sem linha não é problema: o app usa a cotação mais recente com data <= a data procurada
-- (encontrarTasaNaData em lib/moeda.ts).
--
-- A série termina no dia em que a demo foi montada, pra que a última cotação seja "de hoje" e o
-- Dashboard não acuse cotação desatualizada. Daí em diante, a Edge Function atualizar-cotacao-bcv
-- (se ligada no projeto da demo) continua a série a partir dos valores reais, sem salto.
--
-- created_at às 16:00 do próprio dia (horário em que o BCV costuma publicar).
-- Se a data já existir (ex.: a Edge Function já gravou hoje), mantém a existente.
--
-- IDs:
--   cotacao_bcv  d8000000-0000-0000-0000-0000AAAAMMDD   (ex.: ...-000020260325 = 25/03/2026)

begin;

on conflict (data_cotacao) do nothing;

-- Conferência (esperado: 202 cotações, 2026-01-01 a 2026-10-09, de 300,99 a 875,70)
select count(*) as cotacoes, min(data_cotacao), max(data_cotacao), min(tasa_ves), max(tasa_ves)
  from cotacao_bcv
 where data_cotacao between '2026-01-01' and '2026-10-09';

commit;
